css:
.cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.card {
  --bg: #ffffff;
  --fg: #18181b;
  --muted: #71717a;
  --line: #e4e4e7;
  --accent: #f97316;

  padding: 16px;
  border: 1px solid var(--line);
  border-radius: 10px;
  background-color: var(--bg);
  color: var(--fg);
}

.card[data-theme="dark"] {
  --bg: #18181b;
  --fg: #fafafa;
  --muted: #a1a1aa;
  --line: #3f3f46;
  --accent: #fb923c;
}

.card-title {
  margin: 0 0 4px;
}

.card-text {
  margin: 0 0 12px;
  color: var(--muted);
}

.card-btn {
  padding: 6px 12px;
  border: 0;
  border-radius: 6px;
  background-color: var(--accent);
  color: #18181b;
  font: inherit;
}
